changeSet.sql:
INSERT INTO viabilidad_backup (tipo, entidad_id, referencia) SELECT 'INTEGRANTE', ip.id, ip.integrante_proyecto_roles_modalidad_id FROM integrante_proyecto ip JOIN roles_modalidad rm ON rm.id = ip.integrante_proyecto_roles_modalidad_id WHERE rm.rol = 'Viabilidad';
INSERT INTO viabilidad_backup (tipo, entidad_id, authority) SELECT 'USER_AUTH', user_id, authority_name FROM jhi_user_authority WHERE authority_name = 'ROLE_VIABILIDAD';
INSERT INTO viabilidad_backup (tipo, tabla, entidad_id, authority) SELECT 'AUTHORITY', 'proyecto_respuestas', id, authority FROM proyecto_respuestas WHERE authority = 'ROLE_VIABILIDAD';
INSERT INTO viabilidad_backup (tipo, tabla, entidad_id, authority) SELECT 'AUTHORITY', 'adjunto_retroalimentacion', id, authority FROM adjunto_retroalimentacion WHERE authority = 'ROLE_VIABILIDAD';
INSERT INTO viabilidad_backup (tipo, tabla, entidad_id, authority) SELECT 'AUTHORITY', 'pregunta_authority', id, authority_name FROM pregunta_authority WHERE authority_name = 'ROLE_VIABILIDAD';

changeSet.rollback:
UPDATE integrante_proyecto ip
SET integrante_proyecto_roles_modalidad_id = b.referencia
FROM viabilidad_backup b
WHERE b.tipo = 'INTEGRANTE' AND b.entidad_id = ip.id;

DROP TABLE viabilidad_backup;

changeSet.sql:
DELETE FROM jhi_user_authority ua
WHERE ua.authority_name = 'ROLE_VIABILIDAD'
  AND EXISTS (SELECT 1 FROM jhi_user_authority ua2
              WHERE ua2.user_id = ua.user_id AND ua2.authority_name = 'ROLE_JURADO');

UPDATE jhi_user_authority SET authority_name = 'ROLE_JURADO' WHERE authority_name = 'ROLE_VIABILIDAD';

UPDATE proyecto_respuestas SET authority = 'ROLE_JURADO' WHERE authority = 'ROLE_VIABILIDAD';

UPDATE adjunto_retroalimentacion SET authority = 'ROLE_JURADO' WHERE authority = 'ROLE_VIABILIDAD';

UPDATE pregunta_authority SET authority_name = 'ROLE_JURADO' WHERE authority_name = 'ROLE_VIABILIDAD';

changeSet.rollback:
INSERT INTO jhi_user_authority (user_id, authority_name) SELECT entidad_id, 'ROLE_VIABILIDAD' FROM viabilidad_backup WHERE tipo = 'USER_AUTH' AND NOT EXISTS (SELECT 1 FROM jhi_user_authority ua WHERE ua.user_id = viabilidad_backup.entidad_id AND ua.authority_name = 'ROLE_VIABILIDAD');
UPDATE proyecto_respuestas pr SET authority = b.authority FROM viabilidad_backup b WHERE b.tipo = 'AUTHORITY' AND b.tabla = 'proyecto_respuestas' AND b.entidad_id = pr.id;
UPDATE adjunto_retroalimentacion ar SET authority = b.authority FROM viabilidad_backup b WHERE b.tipo = 'AUTHORITY' AND b.tabla = 'adjunto_retroalimentacion' AND b.entidad_id = ar.id;
UPDATE pregunta_authority pa SET authority_name = b.authority FROM viabilidad_backup b WHERE b.tipo = 'AUTHORITY' AND b.tabla = 'pregunta_authority' AND b.entidad_id = pa.id;

