DELETE FROM menu WHERE id = 6516 AND url = '/viabilidad-propuesta/listado';

DELETE FROM roles_modalidad WHERE rol = 'Viabilidad';

DELETE FROM jhi_authority WHERE name = 'ROLE_VIABILIDAD';

